import json, glob, os

facets = {}
for f in glob.glob(os.path.expanduser('~/.claude/usage-data/facets/*.json')):
    sid = os.path.splitext(os.path.basename(f))[0]
    with open(f, encoding='utf-8') as fh:
        try:
            facets[sid] = json.load(fh)
        except:
            pass

keywords = ['copernicus', 'solaris', 'camera', 'digital twin', 'tops', 'pdg', 'render farm', 'render_farm', 'wedge']
relevant = []
for sid, f in facets.items():
    text = json.dumps(f).lower()
    matches = [k for k in keywords if k in text]
    if matches:
        relevant.append({'sid': sid, 'kw': matches, 'sum': f.get('brief_summary',''), 'goal': f.get('underlying_goal',''), 'outcome': f.get('outcome',''), 'type': f.get('session_type','')})

for r in sorted(relevant, key=lambda x: len(x['kw']), reverse=True):
    print(json.dumps(r))
"

