python -c "
import json, glob, os

facets = {}
for f in glob.glob(os.path.expanduser('~/.claude/usage-data/facets/*.json')):
    sid = os.path.splitext(os.path.basename(f))[0]
    with open(f, encoding='utf-8') as fh:
        try:
            facets[sid] = json.load(fh)
        except:
            pass

sessions = []
target = r'c:\users\user\synapse'
for f in glob.glob(os.path.expanduser('~/.claude/usage-data/session-meta/*.json')):
    with open(f, encoding='utf-8') as fh:
        try:
            s = json.load(fh)
            pp = s.get('project_path','').lower().replace('/', os.sep).rstrip(os.sep)
            if pp == target:
                sessions.append(s)
        except:
            pass

sessions.sort(key=lambda x: x.get('start_time',''))
total_mins = sum(s.get('duration_minutes',0) for s in sessions)
total_user = sum(s.get('user_message_count',0) for s in sessions)
total_asst = sum(s.get('assistant_message_count',0) for s in sessions)
total_commits = sum(s.get('git_commits',0) for s in sessions)
total_pushes = sum(s.get('git_pushes',0) for s in sessions)
total_added = sum(s.get('lines_added',0) for s in sessions)
total_removed = sum(s.get('lines_removed',0) for s in sessions)
total_files = sum(s.get('files_modified',0) for s in sessions)

tools = {}
for s in sessions:
    for t, c in s.get('tool_counts',{}).items():
        tools[t] = tools.get(t,0) + c

langs = {}
for s in sessions:
    for l, c in s.get('languages',{}).items():
        langs[l] = langs.get(l,0) + c

# Outcomes from facets
outcomes = {}
types = {}
for s in sessions:
    sid = s['session_id']
    if sid in facets:
        o = facets[sid].get('outcome','unknown')
        outcomes[o] = outcomes.get(o,0) + 1
        t = facets[sid].get('session_type','unknown')
        types[t] = types.get(t,0) + 1

print(f'Sessions: {len(sessions)}')
print(f'Total time: {total_mins//60}h {total_mins%60}m')
print(f'Messages: {total_user} user / {total_asst} assistant')
print(f'Commits: {total_commits}, Pushes: {total_pushes}')
print(f'Lines: +{total_added} / -{total_removed} across {total_files} file edits')
print()
print('Top tools:')
for t, c in sorted(tools.items(), key=lambda x: -x[1])[:12]:
    print(f'  {t}: {c}')
print()
print('Languages:')
for l, c in sorted(langs.items(), key=lambda x: -x[1]):
    print(f'  {l}: {c}')
print()
print('Outcomes:')
for o, c in sorted(outcomes.items(), key=lambda x: -x[1]):
    print(f'  {o}: {c}')
print()
print('Session types:')
for t, c in sorted(types.items(), key=lambda x: -x[1]):
    print(f'  {t}: {c}')
"
